// === Tab: mySketch.js ===
// #RecodeRethink https://openprocessing.org/curation/72108
// Recode: https://openprocessing.org/sketch/2027130
//
// "Not Safe" by ZRNOF
// Inspired by Etienne Jacob (https://bleuje.com/)

const [width, height] = [1280, 1280]

const main = async () => {
	// canvas
	const canvasWebGL2 = document.getElementById("canvasWebGL2")
	const canvas2D = document.getElementById("canvas2D")

	// webgl2 setup
	const gl = canvasWebGL2.getContext("webgl2")
	const program = gl.createProgram()
	setShader(gl, program, vert, frag)
	gl.linkProgram(program)
	gl.useProgram(program)

	// resize
	resizeCanvas(canvasWebGL2, gl, width, height)
	resizeCanvas(canvas2D, gl, width, height)

	// set random value
	const randomVec2 = [random(0, 700), random(0, 1100)]
	const randomVec2Loc = gl.getUniformLocation(program, "uRandomVec2")
	gl.uniform2fv(randomVec2Loc, randomVec2)

	// buffer data
	let positionData = []
	let offsetData = []
	let texCoordData = []

	// generate buffer data
	const cols = width / 4
	const rows = height / 2
	const [xOff, yOff] = [2 / cols, 2 / rows]
	const [uOff, vOff] = [1 / cols, 1 / rows]
	// noprotect
	for (let col = 0; col < cols; col++) {
		for (let row = 0; row < rows; row++) {
			positionData.push(-1 + xOff * col + 1 / cols)
			positionData.push(1 - yOff * row - 1 / rows)
			texCoordData.push((col + 1 / cols) * uOff)
			texCoordData.push((row + 1 / rows) * vOff)
		}
	}

	// set attribute
	setAttributeVec2(gl, program, "aPosition", positionData)
	setAttributeVec2(gl, program, "aTexCoord", texCoordData)

	// set time
	let time = 0
	const timeLoc = gl.getUniformLocation(program, "uTime")

	// draw call
	const draw = () => {
		gl.clearColor(0, 0, 0, 0.1)
		gl.clear(gl.COLOR_BUFFER_BIT)
		gl.uniform1f(timeLoc, time) // time
		gl.drawArrays(gl.POINTS, 0, cols * rows)
		time += 0.02
		drawImage(canvasWebGL2, canvas2D)
		window.requestAnimationFrame(draw)
	}

	draw()
}

main()


// === Tab: tools.js ===
// floor
const floor = (_value) => {
	return Math.floor(_value)
}

// random in range _min to _max
const random = (_min = 0, _max = 1) => {
	return Math.random() * (_max - _min) + _min
}

// draw _drawCanvas to _toCanvas
const drawImage = (_drawCanvas, _toCanvas) => {
	const ctx = _toCanvas.getContext("2d")
	ctx.drawImage(_drawCanvas, 0, 0)
}

// resize canvas and gl viewport
const resizeCanvas = (_canvas, _gl, _width, _height) => {
	_canvas.width = _width
	_canvas.height = _height
	_gl.viewport(0, 0, _canvas.width, _canvas.height)
}

// set vertex shader and fragment shader
const setShader = (_gl, _program, _vert, _frag) => {
	const vertexShader = _gl.createShader(_gl.VERTEX_SHADER)
	_gl.shaderSource(vertexShader, _vert)
	_gl.compileShader(vertexShader)
	_gl.attachShader(_program, vertexShader)

	const fragmentShader = _gl.createShader(_gl.FRAGMENT_SHADER)
	_gl.shaderSource(fragmentShader, _frag)
	_gl.compileShader(fragmentShader)
	_gl.attachShader(_program, fragmentShader)
}

// set vec2 attribute
const setAttributeVec2 = (_gl, _program, _name, _data) => {
	const bufferData = new Float32Array(_data)
	const location = _gl.getAttribLocation(_program, _name)
	const buffer = _gl.createBuffer()
	_gl.bindBuffer(_gl.ARRAY_BUFFER, buffer)
	_gl.bufferData(_gl.ARRAY_BUFFER, bufferData, _gl.STATIC_DRAW)
	_gl.vertexAttribPointer(location, 2, _gl.FLOAT, false, 0, 0)
	_gl.enableVertexAttribArray(location)
}


