	vec2 displace(vec2 uv, vec2 duv, float off, float wei) {
		//uv.x *= iResolution.x/iResolution.y; // square
		duv -= off;
		return uv-duv*wei;
	}

	vec4 displace(vec2 uv, sampler2D img, vec2 duv, float off, float wei) {
		duv -= off;
		return texture(img, uv-duv*wei);
	}
`


// === Tab: shaderSource.js ===
const vert = `#version 300 es
precision highp float;
` + snoise4D + snoise4DImage + displace + `

#define noise snoise4DImage

in vec2 aPosition;
in vec2 aTexCoord;

uniform float uTime;
uniform vec2 uRandomVec2;

out vec2 vTexCoord;
out vec2 vCol; // x=亮度, y=透明度

// --- 随机函数 ---
float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123);
}

// --- 旋转函数 ---
mat3 rotateY(float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return mat3(
        c, 0.0, -s,
        0.0, 1.0, 0.0,
        s, 0.0, c
    );
}

// --- 三角锥几何 ---
void getPyramidGeo(float height, float radius, out vec3 vTop, out vec3 vB1, out vec3 vB2, out vec3 vB3) {
    vTop = vec3(0.0, height, 0.0);
    float baseY = -height;
    float PI = 3.1415926;
    vB1 = vec3(radius * sin(0.0), baseY, radius * cos(0.0));
    vB2 = vec3(radius * sin(2.0*PI/3.0), baseY, radius * cos(2.0*PI/3.0));
    vB3 = vec3(radius * sin(4.0*PI/3.0), baseY, radius * cos(4.0*PI/3.0));
}

// --- 线框插值 ---
vec3 getPyramidEdgePos(float t, vec3 top, vec3 b1, vec3 b2, vec3 b3) {
    float segment = floor(t * 6.0);
    float p = fract(t * 12.0);
    if(segment < 1.0) return mix(top, b1, p);
    if(segment < 2.0) return mix(top, b2, p);
    if(segment < 3.0) return mix(top, b3, p);
    if(segment < 4.0) return mix(b1, b2, p);
    if(segment < 5.0) return mix(b2, b3, p);
    return             mix(b3, b1, p);
}

// --- 锥体内部判断 ---
bool isInsidePyramid(vec3 p, float h, float r) {
    if (p.y > h || p.y < -h) return false;
    float scale = (h - p.y) / (2.0 * h);
    return length(p.xz) < r * scale * 1.6;
}

void main() {
    vTexCoord = aTexCoord;

    // 尺寸
    float halfHeight = 1.3;
    float radius = 0.6;

    vec3 vTop, vB1, vB2, vB3;
    getPyramidGeo(halfHeight, radius, vTop, vB1, vB2, vB3);

    float id = random(aTexCoord);
    bool isWireframe = id < 0.15; 

    vec3 finalPos;
    float brightness = 0.0;
    float alpha = 1.0;
    float ptSize = 1.0;

    // 统一旋转
    float rotSpeed = uTime * 0.4;
    mat3 rot = rotateY(rotSpeed);

    if (isWireframe) {
        // --- 线框逻辑 ---
        float t = id / 0.15;
        vec3 edgePos = getPyramidEdgePos(t, vTop, vB1, vB2, vB3);
        finalPos = rot * edgePos;

        // 线框深度衰减：远处的线稍微暗一点，近处的极亮
        // range roughly -0.6 to 0.6
        float wireDepth = smoothstep(-0.8, 0.8, finalPos.z);
        brightness = 0.5 + wireDepth * 1.5; // 最暗0.5(远)，最亮2.0(近)
        ptSize = 2.0;

    } else {
        // --- 内部烟雾逻辑 ---
        float rX = random(aTexCoord * 10.0);
        float rY = random(aTexCoord * 20.0);
        float rZ = random(aTexCoord * 40.0);

        vec3 rawPos;
        rawPos.y = (rY - 0.5) * 2.0 * halfHeight;
        rawPos.x = (rX - 0.5) * 2.0 * radius;
        rawPos.z = (rZ - 0.5) * 2.0 * radius;

        // 基础裁切
        if (!isInsidePyramid(rawPos, halfHeight, radius)) alpha = 0.0;

        // 异形形状裁切
        vec4 noiseInput = vec4(rawPos * 2.5, uTime * 0.8);
        float shapeNoise = noise(rawPos.xy, 1.0, 1.0, 0.0, 1.0, noiseInput).r;
        if (shapeNoise < 0.05) alpha = 0.0;

        // 内部流动
        vec2 flow = noise(rawPos.xz, 2.0, 1.0, 0.0, 1.0, vec4(0., uTime*0.4, 0., 0.)).rg;
        rawPos += vec3(flow.x, flow.y, 0.0) * 0.1;

        // 应用旋转
        finalPos = rot * rawPos;

        // ===============================================
        // [关键修改] 深度与参差光影逻辑
        // ===============================================

        // 1. 深度基础 (Depth Base)
        // 将 Z 坐标 (-0.6 到 0.6) 映射到亮度。
        // smoothstep(-0.4, 0.5, ...) 让远处(<-0.4)迅速变全黑，近处(>0.5)才变全白
        // 这创造了深邃的黑暗背景。
        float depthBase = smoothstep(-0.4, 0.6, finalPos.z);

        // 2. 参差光影 (Ragged Shimmer)
        // 使用高频噪波模拟破碎的光线。
        // 这里的 uTime * 2.0 让光影移动得比烟雾本身快，产生闪烁感。
        // rawPos * 4.0 让光斑变得细碎。
        float shimmer = noise(rawPos.xy, 4.0, 1.0, 0.5, 1.0, vec4(0., uTime * 2.0, 0., 0.)).r;

        // 提高光影对比度：让亮的地方更亮，暗的地方断开 -> "参差"
        shimmer = smoothstep(0.1, 0.8, shimmer); 

        // 3. 核心发光 (Core)
        // 仅在中心轴保留一点点底光，防止中间全黑
        float core = smoothstep(0.8, 0.0, length(rawPos.xz) / (radius*0.8)) * 0.3;

        // 4. 最终亮度组合
        // 深度 * (参差光影 + 核心)
        // 乘法确保了：如果 depthBase 是 0 (在后面)，那么无论怎么闪烁都是黑的
        brightness = depthBase * (shimmer * 1.2 + core);

        // 粒子大小随亮度剧烈变化
        // 只有被光照亮的地方才显现出来，暗的地方几乎看不见点
        ptSize = 0.5 + brightness * 2.5; 
    }

    // 透视投影
    float cameraDist = 2.5;
    float perspective = 1.0 / (cameraDist - finalPos.z * 1.5);
    gl_Position = vec4(finalPos.xy * perspective, 0.0, 1.0);
    gl_PointSize = ptSize * (perspective * 800.0 / 1280.0);

    vCol = vec2(brightness, alpha);
}
`

const frag = `#version 300 es
precision mediump float;

in vec2 vCol;

out vec4 fragColor;
void main() {
    // 丢弃透明度
    if (vCol.y < 0.01) discard;

    // vCol.x 是亮度
    float b = vCol.x;

    // 如果亮度太低，直接丢弃，让黑色背景更纯净
    if (b < 0.05) discard;

    // 颜色处理：
    // 暗部 (b约0.1-0.3): 深灰蓝/黑
    // 亮部 (b > 0.8): 纯白
    vec3 darkColor = vec3(0.1, 0.12, 0.15); // 深邃的暗部
    vec3 brightColor = vec3(1.0, 1.0, 1.0); // 亮部

    vec3 finalColor = mix(darkColor, brightColor, smoothstep(0.1, 1.0, b));

    fragColor = vec4(finalColor, 1.0);
}
`

